f=reports/ReportsTest.java
sed -i '114i\                Pousada Maré Alta,revenue,2027-06' $f
sed -i '103i\                Pousada Maré Alta,revenue,2027-05' $f
sed -i '87i\                Pousada Maré Alta,revenue,2027-04' $f
sed -i '$d' $f
cat >> $f <<'EOF'

    @Test
    void tourismTaxChargesTheRatePerGuestPerNightOnPaidReservations() {
        String csv = new TourismTaxReport(store, new BigDecimal("4.50")).generate(YearMonth.of(2027, 4));

        // the unpaid and the refunded cancellation are left out
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                total,18.00
                """, csv);
    }

    @Test
    void tourismTaxMultipliesGuestsAndNights() {
        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
        Reservation may = service.create(new NewReservation(
                201, guest, LocalDate.parse("2027-05-10"), LocalDate.parse("2027-05-13"), 2, RatePlan.STANDARD));
        service.confirm(may.id());

        String csv = new TourismTaxReport(store, new BigDecimal("4.50")).generate(YearMonth.of(2027, 5));

        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-05
                reservation,room,check_in,check_out,guests,nights,tax
                6,201,2027-05-10,2027-05-13,2,3,27.00
                total,27.00
                """, csv);
    }

    @Test
    void ratePlansHaveALineEachEvenWithoutReservations() {
        String csv = new RatePlanReport(store).generate(YearMonth.of(2027, 4));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,1,1939.60
                NON_REFUNDABLE,1,212.42
                total,2,2152.02
                """, csv);
    }
}
